import React, { useState, useEffect } from "react";

const Test = () => {
    const [topic, setTopic] = useState("");
    const [topics, setTopics] = useState([]);
    const [questions, setQuestions] = useState([]);
    const [answers, setAnswers] = useState({});
    const [loading, setLoading] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [score, setScore] = useState(0);

    useEffect(() => {
        const savedTopics = JSON.parse(localStorage.getItem("chatTopics")) || [];
        setTopics(savedTopics);
    }, []);

    const fetchAIQuestions = async () => {
        if (!topic) return;
        setLoading(true);
        setQuestions([]);
        setAnswers({});
        setSubmitted(false);
        setScore(0);

        try {
            const response = await fetch("http://localhost:5000/generate-questions", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ topic, numQuestions: 10 }),
            });

            const data = await response.json();
            if (data.questions && data.questions.length > 0) {
                setQuestions(data.questions);
            }
        } catch (error) {
            console.error("Error fetching AI questions:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleAnswerSelect = (questionIndex, selectedOption) => {
        setAnswers((prevAnswers) => ({
            ...prevAnswers,
            [questionIndex]: selectedOption,
        }));
    };

    const handleSubmit = () => {
        let newScore = 0;
        questions.forEach((q, index) => {
            if (answers[index] === q.correctAnswer) {
                newScore++;
            }
        });
        setScore(newScore);
        setSubmitted(true);
    };

    return (
        <div style={{ padding: "20px", backgroundColor: "#fff", color: "#000", maxWidth: "800px", margin: "auto" }}>
            <h2>Generate AI Questions</h2>

            <select value={topic} onChange={(e) => setTopic(e.target.value)} style={{ marginRight: "10px" }}>
                <option value="">Select a Topic</option>
                {topics.length > 0 ? (
                    topics.map((t, index) => <option key={index} value={t}>{t}</option>)
                ) : (
                    <option disabled>No topics found</option>
                )}
            </select>

            <button onClick={fetchAIQuestions} disabled={loading || !topic}>
                {loading ? "Generating..." : "Generate Questions"}
            </button>

            {questions.length > 0 && (
                <div style={{ 
                    height: "400px", 
                    overflowY: "scroll", 
                    border: "1px solid #ccc", 
                    padding: "10px", 
                    marginTop: "20px" 
                }}>
                    <h3>Generated Questions</h3>
                    {questions.map((q, index) => (
                        <div key={index} style={{ marginBottom: "15px", borderBottom: "1px solid #ccc", paddingBottom: "10px" }}>
                            <strong>{index + 1}. {q.question}</strong>
                            <div>
                                {Object.entries(q.options).map(([key, option]) => (
                                    <div key={key}>
                                        <input
                                            type="radio"
                                            name={`question-${index}`}
                                            value={key}
                                            checked={answers[index] === key}
                                            onChange={() => handleAnswerSelect(index, key)}
                                            disabled={submitted}
                                        />
                                        <label style={{ marginLeft: "5px" }}>{option}</label>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {questions.length > 0 && !submitted && (
                <button 
                    onClick={handleSubmit} 
                    style={{ marginTop: "10px", padding: "10px 20px", backgroundColor: "#28a745", color: "#fff", border: "none", cursor: "pointer" }}
                >
                    Submit
                </button>
            )}

            {submitted && (
                <div style={{ marginTop: "20px", padding: "10px", border: "1px solid #ccc", backgroundColor: "#f8f9fa" }}>
                    <h3>Scorecard</h3>
                    <p><strong>Your Score: {score} / {questions.length}</strong></p>
                    <h4>Correct Answers:</h4>
                    <ul>
                        {questions.map((q, index) => (
                            <li key={index}>
                                {q.question} - <strong>{q.options[q.correctAnswer]}</strong>
                            </li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
    );
};

export default Test;
